CREATE DOMAIN positive_input AS integer CHECK(VALUE>0);
SELECT pg_input_is_valid('1','positive_input');
SELECT pg_input_is_valid('-1','positive_input');
SELECT pg_input_is_valid('bad','positive_input');
SELECT sql_error_code FROM pg_input_error_info('-1','positive_input');
SELECT sql_error_code FROM pg_input_error_info('bad','positive_input');
CREATE DOMAIN broken_input AS integer CHECK(VALUE/(VALUE-VALUE)>0);
SELECT pg_input_is_valid('1','broken_input');
SELECT sql_error_code FROM pg_input_error_info('1','broken_input');
CREATE FUNCTION input_check(value integer) RETURNS boolean LANGUAGE plpgsql AS $$BEGIN
    RAISE EXCEPTION USING ERRCODE=current_setting('application_name'), MESSAGE='input expression failed';
END$$;
CREATE DOMAIN checked_input AS integer CHECK(input_check(VALUE));
CREATE TYPE input_record AS (value checked_input);
SET application_name='PZ001';
SELECT pg_input_is_valid('1','checked_input');
SELECT sql_error_code FROM pg_input_error_info('1','checked_input');
SELECT pg_input_is_valid('{1}','checked_input[]');
SELECT sql_error_code FROM pg_input_error_info('{1}','checked_input[]');
SELECT pg_input_is_valid('(1)','input_record');
SELECT sql_error_code FROM pg_input_error_info('(1)','input_record');
